    ///   - optionalFields: specifica la lista dei campi opzionali (che non vengono recupeati di default); impostando il valore `ALL` vengono mostrati tutti i campi. Per gli oggetti è possibile utilizzare la notazione *Ant Glob Patterns* I dettagli sono presenti [qui](https://wiki.u-gov.it/confluence/display/ESSE3/Servizi+REST+su+ESSE3#ServiziRESTsuESSE3-Filtrosuicampidelleclassidimodello) Esempi * per il campo childObj con la poprietà childProp utilizzare la notazione `childProp.prop1` * Per visualizzare tutte le proprietà di childObj utilizzare la notazione `childProp.*` * Per visualizzare tutte le proprietà di childObj e di tutti i discendenti utilizzare la notazione `childProp.**`
    ///   - initialAveragesReferenceDate: data di riferimento iniziale per il calcolo delle medie
    ///   - finalAveragesReferenceDate: data di riferimento finale per il calcolo delle medie
    ///   - pathRulesReason: tipo di regole da utilizzare (default OFFF)
    ///   - dataOriginReason: tipo di origine dati da utilizzare (default LIBRETTO_AD_SUPERATE)
    public func getRecordBookStats(
        matId: Int64,
        optionalFields: String? = nil,
        initialAveragesReferenceDate: String? = nil,
        finalAveragesReferenceDate: String? = nil,
        pathRulesReason: Esse3RecordBookStatsRuleFilter? = nil,
        dataOriginReason: Esse3RecordBookStatsDataOriginFilter? = nil
    ) async throws -> Esse3TranscriptStats {
        try await client.json(
            RestRequest(
                method: .get,
                path: "/libretto-service-v2/libretti/\(RestRequest.pathSegment(matId))/stats",
                query: [
                    ("optionalFields", optionalFields),
                    ("dataRifMedieIni", initialAveragesReferenceDate),
                    ("dataRifMedieFin", finalAveragesReferenceDate),
                    ("motRegolePercorso", pathRulesReason),
                    ("motOrigineDati", dataOriginReason)
                ]
            ),
            roles: [.student, .teacher, .technicalUser]
        )
    }
}
